DO $$
DECLARE
  conflicts int;
BEGIN
  SELECT count(*) INTO conflicts FROM (
    SELECT c."kind", c."provider", c."key_id"
      FROM "credentials" c
     WHERE c."revoked_at" IS NULL
       AND (   c."id" IN (SELECT "credential_id" FROM "mcp_servers"       WHERE "credential_id" IS NOT NULL)
            OR c."id" IN (SELECT "credential_id" FROM "mcp_user_credentials" WHERE "credential_id" IS NOT NULL)
            OR c."id"::text IN (SELECT "configuration" -> 'auth' ->> 'credentialId' FROM "agents"
                                 WHERE "configuration" -> 'auth' ->> 'credentialId' IS NOT NULL))
     GROUP BY c."kind", c."provider", c."key_id"
    HAVING count(*) > 1
  ) g;
  IF conflicts > 0 THEN
    RAISE EXCEPTION 'credentials: % key group(s) have more than one live referenced credential; reconcile manually before migrating', conflicts;
  END IF;
END $$;

