BEGIN
	IF OLD."state" IN ('completed', 'failed', 'cancelled')
		OR (OLD."state" = 'pending' AND NEW."state" NOT IN ('pending', 'running')) THEN
		RAISE EXCEPTION 'illegal execution state transition % -> %', OLD."state", NEW."state"
			USING ERRCODE = 'restrict_violation';
	END IF;
	RETURN NEW;
END;
$$;

