		OR NEW."bot_id" IS DISTINCT FROM OLD."bot_id"
		OR NEW."experiment_id" IS DISTINCT FROM OLD."experiment_id" THEN
		RAISE EXCEPTION 'execution identity is frozen' USING ERRCODE = 'restrict_violation';
	END IF;
	RETURN NEW;
END;
$$;

