export function apiUrl(path: string): string {
  // Absolute (https://…) and protocol-relative (//host…) URLs already carry
  // their own origin — prefixing them would yield "<BASE_PATH>/https://…".
  if (/^(?:[a-z][a-z0-9+.-]*:|\/\/)/i.test(path)) {
    return path;
  }
  const suffix = path.startsWith("/") ? path : `/${path}`;
  return `${BASE_PATH}${suffix}`;
}

