const databaseUrl = process.env.TEST_DATABASE_URL ?? process.env.DATABASE_URL;

if (!databaseUrl) {
  throw new Error(
    "TEST_DATABASE_URL or DATABASE_URL must be configured before running a database migration command",
  );
}

// Surface which connection source won, so destructive DDL is never silently applied to
// the wrong database when both variables are set. Print the variable name, not the URL,
// to avoid leaking credentials into terminal/CI logs.
if (process.env.TEST_DATABASE_URL) {
  console.warn("[drizzle] using TEST_DATABASE_URL; DATABASE_URL is ignored for this run");
}

// Same defense line as configuredBasePath above: Next's allowedDevOrigins
// takes `host` or `host:port` (no scheme, no wildcard), and anything reaching
// this module unfiltered must be judged here, not by the injection side.
const DEV_ORIGIN_PATTERN = /^[A-Za-z0-9._-]+(?::\d{1,5})?(?::\d{1,5})?$/;
const requestedDevOrigins = (process.env.ONYX_WEBAPP_ALLOWED_DEV_ORIGINS || "")
  .split(",")
  .map((origin) => origin.trim())
  .filter(Boolean);
const allowedDevOrigins = requestedDevOrigins.filter((origin) => {
  if (DEV_ORIGIN_PATTERN.test(origin)) return true;
  console.warn(
    `ONYX_WEBAPP_ALLOWED_DEV_ORIGINS entry "${JSON.stringify(origin)}" is not a host[:port] origin; dropped`,
