const data = environment.ENTERPRISE_DATA_DATABASE_URL?.trim();
const runtime = environment.OPENBOT_TENANT_STORAGE_RUNTIME_DATABASE_URL?.trim();

const opened: Array<{ close: () => Promise<void> }> = [];
try {
  const directoryDatabase = createDatabase(directory);
  opened.push(directoryDatabase.$client);
  const dataDatabase = createDatabase(data);
  opened.push(dataDatabase.$client);
  await Promise.all([
    connections.verifyDirectoryDatabase(directoryDatabase),
    connections.verifyDataDatabase(dataDatabase),
  ]);
  ...
} finally {
  for (const client of opened.reverse()) await client.close().catch(() => {});
}

result.push({
  name: "deployment-bare",
  entrance: "deployment",
  notes: [],
  app: await cacheOrBuild(
    "deployment-bare",
    async () =>
      createApp(loadConfig(testEnvironment())) as unknown as RouteApp,
    bypass,
  ),
});
// 建议：逐个装配 try/catch，失败时 push { status: "failed", routeEntries: 0, notes: [reason] }，
// 并在 mergeEntrances 中按 status 输出，而不是让整个命令 reject。

