type Rule = {
  method: string | string[];
  /** 二选一：要么给静态路径模式，要么给自定义匹配（如 CopilotKit 运行时的非锚定路由）。 */
  path?: RegExp;
  matchesPath?: (path: string) => boolean;
  needs: (context: Ctx) => Promise<Capability[]>;
};

const RUNTIME_RUN: Rule = {
  method: "POST",
  matchesPath: (path) => runtimeRun(path) !== null,
  needs: async () => ["useBots"],
};

function matches(rule: Rule, method: string, path: string) {
  const methods = Array.isArray(rule.method) ? rule.method : [rule.method];
  return (
    methods.includes(method) &&
    (rule.matchesPath ? rule.matchesPath(path) : (rule.path ?? /$^/).test(path))
  );
}

