// Allow ~1s of clock skew between the caller's clock and ours.
const skewToleranceMs = 1_000;
if (
  !Number.isFinite(delay) ||
  delay < WAKE_UP_MIN_DELAY_MS - skewToleranceMs
)

.orderBy(
  sql`${workItems.finishedAt} is not null`,
  asc(workItems.runAt),
)
.limit(100);

.set({
  finishedAt: sql`now()`,
  claimedBy: null,
  leaseUntil: null,
  lastError: "Cancelled by reset",
  payload: sql`${workItems.payload} || ${JSON.stringify({
    outcome: { status: "cancelled", at: now().toISOString() },
  })}::text::jsonb`,
  updatedAt: sql`now()`,
})

.where(
  and(
    eq(workItems.kind, WAKE_UP_KIND),
    eq(workItems.key, id),
    isNull(workItems.finishedAt),
    sql`${workItems.payload}->>'outcome' is null`,
  ),
);

const payload = item.payload as unknown as WakeUpPayload;
if (
  !payload?.ownerUserId ||
  !payload.agentId ||
  typeof payload.reason !== "string" ||
  typeof payload.scheduledAt !== "string"
) {
  await done("skipped", "malformed follow-up payload");
  report.skipped.push(item.key);
  continue;
}

await store.settle(item.key, {
  status: "succeeded",
  at: new Date().toISOString(),
});
report.ran.push(item.key);
await queue.finish({
  kind: WAKE_UP_KIND,
  key: item.key,
  owner,
});

} catch (error) {
