export type ObservationBotAccess =
  | {
      ok: true;
      botId: string;
      profile: AgentProfile;
      ownership: ObservationOwnership;
    }
  | { ok: false; status: 404; error: string };

export async function resolveObservationBot(
  check: BotManagementCheck,
  actor: AgentActor,
  botId: string | undefined,
): Promise<ObservationBotAccess> {
  if (!botId)
    return { ok: false, status: 404, error: OBSERVATION_BOT_REQUIRED };
  const profile = await check(actor, botId);
  if (!profile)
    return { ok: false, status: 404, error: OBSERVATION_BOT_NOT_FOUND };
  // Fail closed here, not at each call site: a caller a widened manage gate
  // lets through earns the same unified not-found, never an inferred "admin".
  const ownership = explicitObservationOwnership(actor, profile);
  if (ownership === null)
    return { ok: false, status: 404, error: OBSERVATION_BOT_NOT_FOUND };
  return { ok: true, botId, profile, ownership };
}

