suggestion_code:
export function globMatches(pattern: string, value: string): boolean {
  if (pattern === "*") return true;
  const segments = pattern.split("*");
  if (!value.startsWith(segments[0])) return false;
  if (segments.length === 1) return value === segments[0];
  const tail = segments[segments.length - 1];
  if (tail !== "" && !value.endsWith(tail)) return false;
  let index = segments[0].length;
  const limit = tail === "" ? value.length : value.length - tail.length;
  for (let i = 1; i < segments.length - 1; i += 1) {
    const segment = segments[i];
    if (segment === "") continue;
    const found = value.indexOf(segment, index);
    if (found === -1 || found + segment.length > limit) return false;
    index = found + segment.length;
  }
  return true;
}

