suggestion:
```
function isEnvelope(value: string): boolean {
  // 严格按 encryptSecret 产生的信封判断，而不是靠前缀：OIDC/SAML 配置是 JSON，
  // `{"version":1...}` 开头并不罕见；信封升到 version 2 时，这里若不跟着改，
  // 旧密文会被当成明文再加密一次，之后无法解回。
  try {
    const parsed = JSON.parse(value) as { version?: unknown; iv?: unknown; ciphertext?: unknown };
    return parsed.version === 1 && typeof parsed.iv === "string" && typeof parsed.ciphertext === "string";
  } catch {
    return false;
  }
}
```

