function base64Bytes(text: string): Uint8Array | null {
  const buffer = Buffer.from(text, "base64");
  if (buffer.length === 0) return null;
  // Enforce the round-trip the comment promises: re-encode and compare (padding-insensitive)
  // so a payload Node silently truncated or shifted is never certified.
