suggestion_code:
async function scheduleAfterFailure(
  itemId: string,
): Promise<"scheduled" | "escalated" | "unmatched"> {
  const at = now();
  const [current] = await database
    .select({ failureCount: creditRecoveryItems.failureCount })
    .from(creditRecoveryItems)
    .where(eq(creditRecoveryItems.id, itemId))
    .limit(1);
  if (!current) return "unmatched";
  const escalate = current.failureCount >= config.failureThreshold;
  const updated = await database
    .update(creditRecoveryItems)
    .set({
      ...(escalate
        ? { nextRetryAt: null }
        : {
            nextRetryAt: new Date(
              at.getTime() + retryBackoffMs(current.failureCount, config),
            ),
          }),
      updatedAt: at,
    })
    .where(
      and(
        eq(creditRecoveryItems.id, itemId),
        eq(creditRecoveryItems.state, "pending"),
        eq(creditRecoveryItems.failureCount, current.failureCount),
      ),
    )
    .returning({ id: creditRecoveryItems.id });
  return updated.length === 0 ? "unmatched" : escalate ? "escalated" : "scheduled";
}

