```ts
const ZERO_QUANTITIES = Object.fromEntries(PRICE_DIMENSIONS.map((d) => [d, 0]));
...
const quantities: ReservationBoundQuantities = {
  ...ZERO_QUANTITIES,
  audio_input: inputSeconds,
  output: input.outputTokenCap,
  surcharge_per_request: 1,
