if (!failures.has(hint) && failures.size >= maxHints) {
  // Evict the least recently active hint instead of the earliest inserted one,
  // so an actively-attacked hint is never evicted and its count never resets.
  let victim: string | undefined;
  let oldestAt = Infinity;
  for (const [k, at] of failures) {
    const last = at[at.length - 1];
    if (last < oldestAt) {
      oldestAt = last;
      victim = k;
    }
  }
  if (victim !== undefined) failures.delete(victim);
}

