export async function resolveWorkbenchPayerBinding(
  database: Database,
  scope: PlatformScope,
): Promise<PayerBinding> {
  const ref = resolvePayerForCompanyContext(scope);
  const key = payerKey(ref);
  const cached = bindingCache.get(key);
  if (cached) return cached;
  const existing = await readPayerAccount(database, ref);
  const account = existing ?? (await createPayerAccount(database, ref)).account;
  const binding = restorePayerBinding(account);
  bindingCache.set(key, binding);
  return binding;
}

