// Byte-wise UTF-8 validation: no intermediate string is materialised, so an
// 8 MB upload is not briefly doubled in memory while it is being checked.
function isValidUtf8(bytes: Uint8Array): boolean {
  let i = 0;
  while (i < bytes.length) {
    const byte = bytes[i];
    if (byte < 0x80) {
      i += 1;
      continue;
    }
    let expected = 0;
    let min = 0;
    if ((byte & 0xe0) === 0xc0) {
      expected = 1;
      min = 0x80;
    } else if ((byte & 0xf0) === 0xe0) {
