function sniffImageType(bytes: Uint8Array): string | null {
  // PNG: magic + "IHDR" as the first chunk type (a PNG must open with IHDR).
  if (
    hasSignature(bytes, [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]) &&
    hasSignature(bytes, [0x49, 0x48, 0x44, 0x52], 12)
  ) {
    return "image/png";
  }
  if (hasSignature(bytes, [0xff, 0xd8, 0xff])) return "image/jpeg";
  // GIF87a / GIF89a are the only two signature forms.
  if (hasSignature(bytes, [0x47, 0x49, 0x46, 0x38, 0x37, 0x61])) return "image/gif";
  if (hasSignature(bytes, [0x47, 0x49, 0x46, 0x38, 0x39, 0x61])) return "image/gif";
  // WebP: RIFF....WEBP plus one of the three VP8 chunk tags at offset 12.
  if (
    hasSignature(bytes, [0x52, 0x49, 0x46, 0x46]) &&
    hasSignature(bytes, [0x57, 0x45, 0x42, 0x50], 8) &&
    (hasSignature(bytes, [0x56, 0x50, 0x38, 0x20], 12) ||
      hasSignature(bytes, [0x56, 0x50, 0x38, 0x4c], 12) ||
      hasSignature(bytes, [0x56, 0x50, 0x38, 0x58], 12))
  ) {
    return "image/webp";
  }
  return null;
}
```

