suggestion_code:
function isValidUtf8(bytes: Uint8Array): boolean {
  const CHUNK_BYTES = 64 * 1024;
  // A per-call decoder, NOT the module-level one: `{ stream: true }` leaves
  // a partial UTF-8 sequence buffered between calls, which on a shared
  // instance would leak state across requests.
  const decoder = new TextDecoder("utf-8", { fatal: true });
  for (let offset = 0; offset < bytes.length; offset += CHUNK_BYTES) {
    const isLast = offset + CHUNK_BYTES >= bytes.length;
    try {
      decoder.decode(bytes.subarray(offset, offset + CHUNK_BYTES), {
        stream: !isLast,
      });
    } catch {
      return false;
    }
  }
  return true;
}

