```ts
function isValidUtf8(bytes: Uint8Array): boolean {
  const CHUNK = 64 * 1024;
  const streaming = new TextDecoder("utf-8", { fatal: true });
  for (let i = 0; i < bytes.length; i += CHUNK) {
    const last = i + CHUNK >= bytes.length;
    try {
      streaming.decode(bytes.subarray(i, i + CHUNK), { stream: !last });
    } catch {
      return false;
    }
  }
  return true;
}
```
