 * Whether `next` may replace `held`: forward within one session, always across sessions. The memory
 * store applies it directly; the table mirrors it in `setWhere`, and a table-driven test pins the
 * two together.
 */
function supersedes(
  held: StoredSnapshot | undefined,
  next: StoredSnapshot,
): boolean {
  if (!held) return true;
  if (held.session !== next.session) return true;
  return next.snapshotId > held.snapshotId;
}

