/** Shared prologue: ownership check → 404/empty answer, session dir, and safeJoin → 400. */
const resolveFileContext = async (
  context: Context,
  notFoundError: string,
): Promise<{ fileApi: AgentSandboxFileApi; fullPath: string; rel: string } | Response> => {
  const sessionId = context.req.param("sessionId");
  const rel = context.req.param("path") ?? "";
  const { session, fileApi } = await resolve(sessionId, context.var.actor.id);
  if (!session) return context.json({ error: "Session not found" }, 404);
  if (!fileApi) return context.json({ error: notFoundError }, 404);
  const fullPath = safeJoin(sessionDirectory(sessionId, deps.config.sessionDirectoryMode), rel);
  if (fullPath === null) {
    return context.json({ error: "Path is outside the session workspace." }, 400);
  }
  return { fileApi, fullPath, rel };
};

