let pluginSourcePromise: Promise<string> | null = null;

export function connectAppPluginSource(): Promise<string> {
  pluginSourcePromise ??= readFile(
    new URL("./templates/connect-app.plugin.ts", import.meta.url),
    "utf8",
  ).catch((err) => {
    pluginSourcePromise = null; // 失败不缓存，下次重试
    throw new Error(
      `connect-app plugin template unreadable (is templates/ included in the build output?): ${String(err)}`,
    );
  });
  return pluginSourcePromise;
}

