export async function writeConnectAppPlugin(
  api: { writeFile(path: string, content: string): Promise<void> },
  sessionId: string,
  config: CraftConfig,
): Promise<void> {
  const target = `${sessionDirectory(sessionId, config.sessionDirectoryMode)}/${CONNECT_APP_PLUGIN_RELPATH}`;
  try {
    await api.writeFile(target, await connectAppPluginSource());
  } catch (err) {
    throw new Error(`writeConnectAppPlugin failed for session ${sessionId} at ${target}: ${String(err)}`, { cause: err });
  }
}

