export async function writeWebappPlugin(
  api: { writeFile(path: string, content: string): Promise<void> },
  sessionId: string,
  config: CraftConfig,
): Promise<void> {
  const path = `${sessionDirectory(
    sessionId,
    config.sessionDirectoryMode,
  )}/${WEBAPP_PLUGIN_RELPATH}`;
  try {
    await api.writeFile(path, await webappPluginSource());
  } catch (error) {
    throw new Error(
      `[craft] failed to write webapp plugin for session ${sessionId} at ${path}: ${
        error instanceof Error ? error.message : String(error)
      }`,
      { cause: error },
    );
  }
}

