const BILLING_MANAGE_ACTION_BITS: Record<BillingManageAction, number> = {
  grant: 1,
  adjust: 2,
  refund: 4,
};

/** 动作→授权位（发放=1、调整=2、退款=4）。 */
export function billingManageActionBit(action: BillingManageAction): number {
  return BILLING_MANAGE_ACTION_BITS[action];
}

/** 全部动作位按位或（随 BILLING_MANAGE_ACTIONS 自动同步）。 */
export const BILLING_MANAGE_ALL_ACTIONS = BILLING_MANAGE_ACTIONS.reduce(
  (bits, action) => bits | BILLING_MANAGE_ACTION_BITS[action],
  0,
);

