-- 迁移中最小列级授权 + 终态不可逆触发器
GRANT UPDATE (status, consumed_at, failed_at, failed_reason)
  ON enterprise_oauth_states TO ob_ent_operator;

CREATE FUNCTION enterprise_oauth_state_immutable() RETURNS trigger AS $$
BEGIN
  IF OLD.status <> 'pending' THEN
    RAISE EXCEPTION 'oauth state % already terminal (%)', OLD.id, OLD.status;
  END IF;
  IF NEW.id <> OLD.id OR NEW.tenant_id <> OLD.tenant_id
     OR NEW.workspace_id <> OLD.workspace_id OR NEW.principal_id <> OLD.principal_id
     OR NEW.purpose <> OLD.purpose OR NEW.target <> OLD.target
     OR NEW.verifier <> OLD.verifier OR NEW.expires_at <> OLD.expires_at THEN
    RAISE EXCEPTION 'oauth state % initiation fields are immutable', OLD.id;
  END IF;
  RETURN NEW;
END $$ LANGUAGE plpgsql;

CREATE TRIGGER enterprise_oauth_state_guard BEFORE UPDATE ON enterprise_oauth_states
  FOR EACH ROW EXECUTE FUNCTION enterprise_oauth_state_immutable();

