interface FailureRecord extends DesktopConnectionFailure {
  readonly createdAt: number;
}

const FAILURE_TTL_MS = 5 * 60 * 1000;

const failures = new Map<
  DesktopConnectionFailure["connection"],
  FailureRecord
>();

export function recordDesktopConnectionFailure(
  failure: DesktopConnectionFailure,
): void {
  failures.set(failure.connection, { ...failure, createdAt: Date.now() });
}

function pruneExpiredFailures(): void {
  const now = Date.now();
  for (const [key, record] of failures) {
    if (now - record.createdAt > FAILURE_TTL_MS) failures.delete(key);
  }
}

