export function runOutputCeilingFromInput(input: unknown): number {
  if (!isPlainRecord(input)) throw new Error("RUN_OUTPUT_CEILING_INPUT_INVALID");
  const { forwardedProps } = input;
  if (!isPlainRecord(forwardedProps)) {
    throw new Error("RUN_OUTPUT_CEILING_FORWARDED_PROPS_REQUIRED");
  }
  const { maxOutputTokens } = forwardedProps;
  if (maxOutputTokens === undefined) {
    throw new Error("RUN_OUTPUT_CEILING_REQUIRED");
  }
  if (!isPositiveInt32TokenCount(maxOutputTokens)) {
    throw new Error("RUN_OUTPUT_CEILING_TOKENS_INVALID");
  }
  return Math.min(maxOutputTokens, MAXIMUM_RUN_OUTPUT_TOKENS);
}
```

