对于评论 1 的建议代码:

```ts
export function publicOperationError(
  code: OperationErrorCode,
  requestId: string,
): z.infer<typeof OperationErrorEnvelopeSchema> {
  const result = OperationErrorEnvelopeSchema.safeParse({
    error: {
      code,
      message: PUBLIC_MESSAGES[code],
      request_id: requestId,
    },
  });
  // Never throw on the error-handling path; fall back to a safe envelope.
  if (!result.success) {
    return {
      error: { code: "internal", message: "Request failed.", request_id: "unknown" },
    };
  }
  return result.data;
}
```

