205: export function buildReadinessGapReport(
206:   record: MultitenancyReadinessEnforcementRecord,
207: ): ReadinessGapReport {
208:   const gaps: ReadinessGap[] = [];
209:   if (record.mode === "off") {
210:     return {
211:       schemaVersion: 1,
212:       type: "multitenancy-readiness-gap-report",
213:       accepted: true,
214:       generatedAt: record.timestamp,
215:       gaps,
216:     };
217:   }
218:   const { startup, quarantine } = record.checks;
219:   if (!startup.checks.coverage.ok) {
220:     gaps.push({ check: "coverage", detail: startup.checks.coverage.reason });
221:     for (const uncovered of startup.checks.coverage.uncovered) {
222:       gaps.push({
223:         check: "coverage",
224:         code:
225:           uncovered.reason === "unowned"
226:             ? "UNOWNED_ENTRANCE"
227:             : "UNCLASSIFIED_ENTRANCE",
228:         detail: `${uncovered.entrance} is ${uncovered.reason} — every entrance must be owned and classified before multitenancy boots (explicit waivers are the only relaxation and each carries a reason)`,
229:       });
230:     }
231:   }
232:   if (!startup.checks.devBypass.ok) {
233:     for (const finding of startup.checks.devBypass.findings) {
234:       gaps.push({
235:         check: "devBypass",
236:         detail: `${finding.source}: ${finding.detail}`,
237:       });
238:     }
239:   }
240:   if (!startup.checks.databaseRoles.ok) {
241:     gaps.push({
242:       check: "databaseRoles",
243:       detail: startup.checks.databaseRoles.reason,
244:     });
245:   }
246:   if (!startup.checks.globalExceptions.ok) {
247:     for (const finding of startup.checks.globalExceptions.findings) {
248:       gaps.push({
249:         check: "globalExceptions",
250:         code: finding.code,
251:         detail: finding.detail,
252:       });
253:     }
254:   }
255:   if (!startup.checks.machinePersonalExceptions.ok) {
256:     for (const finding of startup.checks.machinePersonalExceptions.findings) {
257:       gaps.push({
258:         check: "machinePersonalExceptions",
259:         code: finding.code,
260:         detail: finding.detail,
261:       });
262:     }
263:   }
264:   if (!quarantine.ok) {
265:     gaps.push({ check: "quarantine", detail: quarantine.reason });
266:   }
267:   return {
268:     schemaVersion: 1,
269:     type: "multitenancy-readiness-gap-report",
270:     accepted: gaps.length === 0,
271:     generatedAt: record.timestamp,
272:     gaps,
273:   };
274: }
