function createDrizzleDegradedSearch<T extends HindsightRecordTable>(
  database: Database,
  table: T,
) {
  return {
    async loadRecallEligible(tenantId: string, principalId: string) {
      return database
        .select()
        .from(table)
        .where(
          and(
            eq(table.tenantId, tenantId),
            eq(table.principalId, principalId),
            or(eq(table.reviewState, "confirmed"), eq(table.reviewState, "edited")),
            eq(table.enabled, true),
            isNull(table.deletedAt),
            ne(table.content, ""),
          ),
        )
        .orderBy(desc(table.updatedAt));
    },
  };
}

