// ...
function dropReasonOf(
  definition: FrontendToolDefinition | undefined,
  name: unknown,
  granted: ReadonlySet<string>,
  mounted: ReadonlySet<string>,
): string | null {
  if (!definition || typeof name !== "string") return "invalid declaration (no string name)";
  if (!VALID_BRIDGE_TOOL_NAME.test(name)) return "invalid tool name";
  if (isReservedToolName(name)) return "reserved tool name";
  if (granted.has(name)) return "collides with a granted (server-executed) tool";
  if (mounted.has(name)) return "duplicate client declaration";
  return null;
}
```

