suggestion_code:
function stripMastraRequestBookkeeping<T>(
  value: T,
  seen: WeakSet<object> = new WeakSet(),
): T {
  if (Array.isArray(value)) {
    return value.map((entry) =>
      stripMastraRequestBookkeeping(entry, seen),
    ) as unknown as T;
  }
  if (isPlainObject(value)) {
    if (seen.has(value)) {
      throw new Error("cyclic value in request bookkeeping strip");
    }
    seen.add(value);
    const record = value as Record<string, unknown>;
    const cleaned: Record<string, unknown> = {};
    for (const [key, child] of Object.entries(record)) {
      if (
        key === "providerOptions" &&
        child &&
        typeof child === "object" &&
        !Array.isArray(child) &&
        Object.keys(child as Record<string, unknown>).every((name) =>
          MASTRA_BOOKKEEPING_KEYS.includes(name),
        )
      ) {
        continue;
      }
      cleaned[key] = stripMastraRequestBookkeeping(child, seen);
    }
    return cleaned as unknown as T;
  }
  return value;
}

