/** 共享比较器:先 receivedAt 再 id;`direction` 为 -1 即最新在前,1 即最旧在前。 */
function compareByReceivedAt(direction: 1 | -1) {
  return (left: OpenMuseMailMessage, right: OpenMuseMailMessage): number => {
    const leftAt = Date.parse(left.receivedAt);
    const rightAt = Date.parse(right.receivedAt);
    if (leftAt !== rightAt) return (rightAt - leftAt) * direction;
    return (left.id < right.id ? -1 : left.id > right.id ? 1 : 0) * direction;
  };
}

export function sortNewestFirst(messages: OpenMuseMailMessage[]) {
  return [...messages].sort(compareByReceivedAt(-1));
}

export function sortOldestFirst(messages: OpenMuseMailMessage[]) {
  return [...messages].sort(compareByReceivedAt(1));
}

