    const leftAt = Date.parse(left.receivedAt);
    const rightAt = Date.parse(right.receivedAt);
    if (leftAt !== rightAt) return rightAt - leftAt;
    if (right.id < left.id) return -1;
    if (right.id > left.id) return 1;
    return 0;
  });
