function scrub(text: string, secrets: (string | undefined)[]): string {
  let out = text;
  for (const secret of secrets)
    if (secret && secret.length >= 3) {
      out = out.split(secret).join("[hidden]");
      out = out.split(encodeURIComponent(secret)).join("[hidden]");
    }
  return out.slice(0, MAX_OUTCOME_LENGTH);
}

