/** Comparison-only domain separator (public, not a secret): hashing both sides under a fixed key
 * keeps the bearer comparison constant-time over equal-length digests. */
const BEARER_DIGEST_DOMAIN = "openbot-bearer";

export function verifyBearer(secret: string, header: string | undefined) {
  const match = /^Bearer\s+(\S+)$/i.exec(header?.trim() ?? "");
  if (!match?.[1]) return false;
  const digest = (value: string) =>
    createHmac("sha256", BEARER_DIGEST_DOMAIN).update(value).digest();
  return safeEqual(digest(match[1]), digest(secret));
}

