/** Internal, server-trusted shape; never parse untrusted request bodies with it. */
export const internalResponsibilityEventSchema = responsibilityEventSchema.extend({
  triggerId: text(128).optional(),
});
```
并把公开 schema 中的 triggerId 移除/设为 never。给出建议代码:
```ts
export const responsibilityEventSchema = z
  .object({
    ...
    responsibilityId: text(128).optional(),
  })
  .strict()
  .superRefine(...);

/** Server-side only: ingress routes that verified a trigger extend the public shape. */
export const trustedResponsibilityEventSchema = responsibilityEventSchema.extend({
  triggerId: text(128).optional(),
}).strict()
  .superRefine((event, context) => {
    if (event.triggerId && !event.responsibilityId)
      context.addIssue({ code: "custom", message: "A trigger event must name its responsibility." });
  });
```
太长,简化。suggestion_code 简短一些。

