const refusedMessage = (error: z.ZodError) =>
  error.issues
    .map((issue) =>
      issue.path.length ? `${issue.path.join(".")}: ${issue.message}` : issue.message,
    )
    .join("; ") || "Invalid input.";
export function parseResponsibilityEvent(input: unknown): ResponsibilityEvent {
  const result = responsibilityEventSchema.safeParse(input);
  if (!result.success) throw new ResponsibilityRefusedError(refusedMessage(result.error));
  return result.data;
}
```

