/**
 * The origin to write on a usage fact: the innermost established one, or `unknown` when no
 * surface claimed the call. Nested calls override, so an internal dispatch named `api` under
 * the session middleware's `web` stays `api`.
 *
 * Doors must wrap the SMALLEST unit: continuations created inside `fn` — fire-and-forget
 * promises, timers, event subscriptions — keep this origin after the unit ends, so detach
 * only after capturing the origin explicitly (the trace/scope discipline in copilot.ts's
 * doStream: capture at entry, carry the value on the fact).
 */
export function currentUsageOrigin(): UsageOrigin {
  return originStore.getStore()?.origin ?? "unknown";
}

