  setup: Database,
  statement: ReturnType<typeof sql>,
  label: string,
): Promise<void> {
  await setup.transaction(async (tx) => {
    await tx.execute(sql`set local lock_timeout = '2s'`);
    await tx.execute(sql`set local statement_timeout = '5s'`);
    const updated = (await tx.execute(statement)) as unknown as {
      count?: number;
    };
    if (typeof updated?.count !== "number") {
      throw new Error(`${label}_COUNT_SHAPE_UNSUPPORTED`);
    }
    if (updated.count !== 1) {
      throw new Error(`${label}_FAILED:${updated.count}`);
    }
  });
}

