async function teardownPreferencesFixture(initial: unknown[]): Promise<never> {
  const failures = [...initial];
  try {
    await setupDatabase.delete(users).where(like(users.id, `${prefix}%`));
  } catch (cleanupError) {
    failures.push(cleanupError);
  }
  for (const closeable of closeables.reverse()) {
    try {
      await closeable.close();
    } catch (closeError) {
      failures.push(closeError);
    }
  }
  try {
    await runtime.dispose();
  } catch (disposeError) {
    failures.push(disposeError);
  }
  if (failures.length) throw new AggregateError(failures, "Preferences fixture cleanup failed.");
  throw undefined as never;
}

