function isValidObservation(
  observation: unknown,
): observation is IsolationObservation {
  if (typeof observation !== "object" || observation === null) {
    return false;
  }
  const value = observation as Record<string, unknown>;
  return (
    typeof value.positiveControlPassed === "boolean" &&
    typeof value.denied === "boolean" &&
    Array.isArray(value.leakedRecords) &&
    Array.isArray(value.forbiddenEffects)
  );
}

