```ts
const TABLE = "gateway_rate_versions";
const TRIGGERS = ["gateway_rate_versions_append_only", "gateway_rate_versions_no_truncate"] as const;

async function setTriggers(
  database: { execute: (query: SQL) => Promise<unknown> },
  mode: "DISABLE" | "ENABLE",
) {
  for (const trigger of TRIGGERS) {
    await database.execute(
      sql`ALTER TABLE ${sql.identifier(TABLE)} ${sql.raw(mode)} TRIGGER ${sql.identifier(trigger)}`,
    );
  }
}
```

